<?php
$filters=['date'=>is_string($_GET['date']??null)?$_GET['date']:'','status'=>is_string($_GET['status']??null)?$_GET['status']:'','search'=>is_string($_GET['search']??null)?$_GET['search']:'','page'=>is_string($_GET['page']??null)?$_GET['page']:'1'];
$filters['customer_id']=is_string($_GET['customer_id']??null)?$_GET['customer_id']:'';
$rows=admin_appointments($filters);
?>
<?php if ($filters['customer_id'] !== ''): ?><p class="small-note">Showing reservations for the selected customer. <a class="text-link" href="<?= e(url('/admin/customers.php')) ?>">Customer records ↗</a></p><?php endif; ?>
<form method="get" class="admin-filters"><?php if ($filters['customer_id'] !== ''): ?><input type="hidden" name="customer_id" value="<?= e($filters['customer_id']) ?>"><?php endif; ?><div class="field"><label for="admin-search">Customer, email or booking reference</label><input id="admin-search" name="search" maxlength="100" value="<?= e($filters['search']) ?>"></div><div class="field"><label for="filter-date">Appointment date · optional</label><input id="filter-date" type="date" name="date" value="<?= e($filters['date']) ?>"></div><div class="field"><label for="filter-status">Status</label><select id="filter-status" name="status"><option value="">All statuses</option><?php foreach(['pending','awaiting_payment','confirmed','ongoing','completed','cancelled','no_show','expired'] as $status): ?><option value="<?= e($status) ?>" <?= $filters['status']===$status?'selected':'' ?>><?= e(appointment_status_label($status)) ?></option><?php endforeach; ?></select></div><button class="button" type="submit">Search appointments ↗</button><a class="text-link" href="<?= e(url('/admin/appointments.php')) ?>">Clear filters</a></form>
<div class="table-scroll" tabindex="0" role="region" aria-label="Appointments"><table class="admin-table"><thead><tr><?php foreach(['Reference','Customer','Treatment','Room','Therapist','Guests','Date','Start–end','Total','Amount recorded','Remaining balance','Status','Action'] as $label): ?><th><?= e($label) ?></th><?php endforeach; ?></tr></thead><tbody>
<?php foreach($rows as $a):$s=payment_summary($a); ?><tr><td class="booking-reference"><?= e($a['booking_reference']) ?></td><td><?= e($a['customer_name']) ?></td><td><?= e($a['service_name_snapshot']?:$a['catalog_name']) ?></td><td><?= e($a['room_code']) ?></td><td><?= e(staff_display_name($a['therapist_names']?:'Not assigned')) ?></td><td><?= e($a['guest_count']) ?></td><td><?= e(local_time($a['starts_at'])->format('Y-m-d')) ?></td><td><?= e(local_time($a['starts_at'])->format('g:i A').'–'.local_time($a['ends_at'])->format('g:i A')) ?></td><td><?= peso_amount($s['total']) ?></td><td><?= peso_amount($s['paid']) ?></td><td><?= peso_amount($s['balance']) ?><small><?= $s['is_demo']?'Test Mode':'Provider ledger' ?></small></td><td><?= e(appointment_status_label($a['status'])) ?><small><?= e(payment_status_label($a)) ?></small></td><td><a href="<?= e(url('/admin/appointment.php?reference='.rawurlencode($a['booking_reference']))) ?>">View & manage ↗</a></td></tr><?php endforeach; ?>
</tbody></table></div><?php if(!$rows): ?><p class="notice">No appointments match these filters.</p><?php endif; ?>
<div class="inline-actions"><?php if((int)$filters['page']>1): ?><a href="<?= e(url('/admin/appointments.php?'.http_build_query(array_replace($filters,['page'=>(int)$filters['page']-1])))) ?>">Previous page</a><?php endif;if(count($rows)===200): ?><a href="<?= e(url('/admin/appointments.php?'.http_build_query(array_replace($filters,['page'=>(int)$filters['page']+1])))) ?>">Next page</a><?php endif; ?></div>
